#include <vector>
#include <algorithm>

class Solution {
public:
    std::vector<int> maximumBeauty(std::vector<std::vector<int>>& items, std::vector<int>& queries) {
        std::sort(items.begin(), items.end(), [](const auto& a, const auto& b) {
            return a[0] < b[0];
        });

        int n = items.size();
        std::vector<int> prices(n);
        std::vector<int> maxBeauty(n);
        int curMax = 0;
        for (int i = 0; i < n; ++i) {
            prices[i] = items[i][0];
            curMax = std::max(curMax, items[i][1]);
            maxBeauty[i] = curMax;
        }

        std::vector<int> res;
        res.reserve(queries.size());
        for (int q : queries) {
            auto it = std::upper_bound(prices.begin(), prices.end(), q);
            int idx = std::distance(prices.begin(), it) - 1;
            res.push_back(idx >= 0 ? maxBeauty[idx] : 0);
        }
        return res;
    }
};

import java.util.Arrays;

class Solution {
    public int[] maximumBeauty(int[][] items, int[] queries) {
        Arrays.sort(items, (a, b) -> Integer.compare(a[0], b[0]));
        int n = items.length;
        int[] prices = new int[n];
        int[] maxBeauty = new int[n];
        int curMax = 0;
        for (int i = 0; i < n; i++) {
            prices[i] = items[i][0];
            curMax = Math.max(curMax, items[i][1]);
            maxBeauty[i] = curMax;
        }

        int[] res = new int[queries.length];
        for (int i = 0; i < queries.length; i++) {
            int q = queries[i];
            int idx = upperBound(prices, q) - 1;
            res[i] = (idx >= 0) ? maxBeauty[idx] : 0;
        }
        return res;
    }

    private int upperBound(int[] arr, int target) {
        int lo = 0, hi = arr.length;
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (arr[mid] <= target) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }
}

/**
 * @param {number[][]} items
 * @param {number[]} queries
 * @return {number[]}
 */
var maximumBeauty = function(items, queries) {
    items.sort((a, b) => a[0] - b[0]);
    const n = items.length;
    const prices = new Int32Array(n);
    const maxBeauty = new Int32Array(n);
    let curMax = 0;
    for (let i = 0; i < n; i++) {
        prices[i] = items[i][0];
        curMax = Math.max(curMax, items[i][1]);
        maxBeauty[i] = curMax;
    }

    const res = new Int32Array(queries.length);
    for (let i = 0; i < queries.length; i++) {
        const q = queries[i];
        let lo = 0, hi = n;
        while (lo < hi) {
            const mid = (lo + hi) >> 1;
            if (prices[mid] <= q) lo = mid + 1;
            else hi = mid;
        }
        const idx = lo - 1;
        res[i] = (idx >= 0) ? maxBeauty[idx] : 0;
    }
    return Array.from(res);
};
